import os
import json
import hmac
import hashlib
import time
import logging
from base64 import b64encode, b64decode
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding as sym_padding
from cryptography.hazmat.backends import default_backend
from flask import Flask, request, jsonify, g

app = Flask(__name__)
logger = logging.getLogger('audit')
logger.setLevel(logging.INFO)
handler = logging.FileHandler('/var/log/mobile_api/audit.log')
handler.setFormatter(logging.Formatter('%(asctime)s %(message)s'))
logger.addHandler(handler)

ENCRYPTION_KEY = os.environ.get('API_ENC_KEY', os.urandom(32))
HMAC_KEY = os.environ.get('API_HMAC_KEY', os.urandom(32))

class TokenError(Exception):
    pass

def compute_hmac(data: bytes) -> bytes:
    return hmac.new(HMAC_KEY if isinstance(HMAC_KEY, bytes) else HMAC_KEY.encode(), data, hashlib.sha256).digest()

def encrypt_token(payload: dict) -> str:
    plaintext = json.dumps(payload).encode('utf-8')
    padder = sym_padding.PKCS7(128).padder()
    padded = padder.update(plaintext) + padder.finalize()
    iv = os.urandom(16)
    cipher = Cipher(algorithms.AES(ENCRYPTION_KEY if isinstance(ENCRYPTION_KEY, bytes) else ENCRYPTION_KEY.encode()[:32]), modes.CBC(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    ciphertext = encryptor.update(padded) + encryptor.finalize()
    token_data = iv + ciphertext
    mac = compute_hmac(token_data)
    return b64encode(token_data + mac).decode('ascii')

def decrypt_token(token_str: str) -> dict:
    """Decrypt and verify a session token with integrity check."""
    try:
        raw = b64decode(token_str)
    except Exception:
        raise TokenError("Invalid token")

    if len(raw) < 48:  # 16 IV + 16 min ciphertext + 32 HMAC
        raise TokenError("Invalid token")

    token_data = raw[:-32]
    provided_mac = raw[-32:]

    # Verify HMAC first - this prevents any padding oracle
    expected_mac = compute_hmac(token_data)
    if not hmac.compare_digest(expected_mac, provided_mac):
        raise TokenError("Invalid token")

    iv = token_data[:16]
    ciphertext = token_data[16:]

    cipher = Cipher(algorithms.AES(ENCRYPTION_KEY if isinstance(ENCRYPTION_KEY, bytes) else ENCRYPTION_KEY.encode()[:32]), modes.CBC(iv), backend=default_backend())
    decryptor = cipher.decryptor()
    padded_plaintext = decryptor.update(ciphertext) + decryptor.finalize()

    # Use library padding validation - no distinct error type
    try:
        unpadder = sym_padding.PKCS7(128).unpadder()
        plaintext = unpadder.update(padded_plaintext) + unpadder.finalize()
    except Exception:
        raise TokenError("Invalid token")

    try:
        return json.loads(plaintext.decode('utf-8'))
    except Exception:
        raise TokenError("Invalid token")

def _audit_token_operation(operation: str, token_fragment: str, result: str):
    """Log token operations for security audit trail."""
    entry = {
        'op': operation,
        'token_prefix': token_fragment[:8] if token_fragment else 'N/A',
        'result': result,
        'ts': time.time(),
        'ip': request.remote_addr if request else 'internal'
    }
    logger.info(json.dumps(entry))

@app.before_request
def authenticate():
    """Authenticate requests using encrypted session tokens."""
    public_paths = ['/api/v1/auth/login', '/api/v1/health']
    if request.path in public_paths:
        return None

    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        _audit_token_operation('auth', '', 'failed')
        return jsonify({'error': 'Authorization required'}), 401

    token = auth_header[7:]
    try:
        payload = decrypt_token(token)
        g.user = payload
        _audit_token_operation('auth', token, 'success')
    except TokenError:
        _audit_token_operation('auth', token, 'failed')
        return jsonify({'error': 'Invalid session token'}), 401
    except Exception:
        _audit_token_operation('auth', token, 'failed')
        return jsonify({'error': 'Authentication failed'}), 401

    return None

@app.route('/api/v1/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    payload = {
        'sub': data['username'],
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600,
        'role': 'user'
    }
    token = encrypt_token(payload)
    _audit_token_operation('login', token, 'success')
    return jsonify({'token': token, 'expires_in': 3600})

@app.route('/api/v1/user/profile')
def profile():
    return jsonify({'user': g.user})

@app.route('/api/v1/user/refresh', methods=['POST'])
def refresh():
    if g.user.get('exp', 0) < time.time() + 300:
        new_payload = {**g.user, 'exp': int(time.time()) + 3600, 'iat': int(time.time())}
        new_token = encrypt_token(new_payload)
        _audit_token_operation('refresh', new_token, 'success')
        return jsonify({'token': new_token, 'expires_in': 3600})
    return jsonify({'message': 'Token still valid', 'token': request.headers.get('Authorization', '')[7:]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
